/**
 * Hand-written: the generator pins no box shadows, and the two hairline frames
 * behind a Work's cover are the tile's whole "more than one" (Work-Library,
 * B1). They are the cover's own box-shadow, at 5px and 10px.
 */
test('The library with Works: the tile stands two hairline frames behind the cover', async ({
	page
}) => {
	await page.goto(`${base}/`);
	const shadow = await page
		.locator('.grid .tile.work .frames')
		.first()
		.evaluate((node) => getComputedStyle(node).boxShadow);
	expect(shadow).toContain('5px -5px');
	expect(shadow).toContain('10px -10px');
});
